fn longest_word(text: &str) -> &str {
    let mut best = "";
    for w in text.split_whitespace() {
        if w.chars().count() > best.chars().count() {
            best = w;
        }
    }
    best
}

fn pick<'a>(a: &'a str, b: &'a str, first: bool) -> &'a str {
    if first { a } else { b }
}

fn split_pair(line: &str, sep: char) -> Option<(&str, &str)> {
    let (k, v) = line.split_once(sep)?;
    Some((k.trim(), v.trim()))
}

struct Tokenizer<'a> {
    rest: &'a str,
}

impl<'a> Tokenizer<'a> {
    fn new(text: &'a str) -> Self {
        Tokenizer { rest: text }
    }

    fn next_token(&mut self) -> Option<&'a str> {
        self.rest = self.rest.trim_start();
        let first = self.rest.chars().next()?;
        let len = if first.is_alphabetic() {
            self.rest.find(|c: char| !c.is_alphabetic()).unwrap_or(self.rest.len())
        } else if first.is_ascii_digit() {
            self.rest.find(|c: char| !c.is_ascii_digit()).unwrap_or(self.rest.len())
        } else {
            match self.rest.char_indices().nth(1) {
                Some((i, _)) => i,
                None => self.rest.len(),
            }
        };
        let (token, rest) = self.rest.split_at(len);
        self.rest = rest;
        Some(token)
    }
}

unitTests:
test("longest word", || {
    let text = String::from("the quick brownish fox");
    let w = longest_word(&text);
    check_eq(w, "brownish");
    check_eq(longest_word("tie two"), "tie");
    check_eq(longest_word("   "), "");
});

test("pick and split", || {
    let a = String::from("left");
    check_eq(pick(&a, "right", true), "left");
    check_eq(pick(&a, "right", false), "right");
    check_eq(split_pair(" key = value ", '='), Some(("key", "value")));
    check_eq(split_pair("a:b:c", ':'), Some(("a", "b:c")));
    check_eq(split_pair("nothing", '='), None);
});

test("tokens borrow from the text", || {
    let source = String::from("x1 = 42+y;");
    let tokens: Vec<&str> = {
        let mut t = Tokenizer::new(&source);
        let mut out = Vec::new();
        while let Some(tok) = t.next_token() {
            out.push(tok);
        }
        out
    };
    check_eq(tokens, vec!["x", "1", "=", "42", "+", "y", ";"]);
    let mut t = Tokenizer::new("  ");
    check_eq(t.next_token(), None);
    let mut u = Tokenizer::new("héllo→wörld");
    check_eq(u.next_token(), Some("héllo"));
    check_eq(u.next_token(), Some("→"));
    check_eq(u.next_token(), Some("wörld"));
});

